/// Registre des méthodes : statut de validation, conditions, diagnostics,
/// résultats, leçon associée et logiciel de référence. C'est aussi la source
/// de la matrice « question → données requises → méthode → conditions →
/// diagnostics → résultat » (livrable 2), générée par [methodMatrixMarkdown].
library;

import '../i18n.dart';
import '../model/result.dart';

class MethodInfo {
  final String id;
  final String name;
  final String category;
  final MethodStatus status;
  final String question;
  final String requiredData;
  final List<String> conditions;
  final List<String> diagnostics;
  final String output;
  final String lessonId;
  final String reference; // logiciel de référence utilisé pour la validation
  const MethodInfo({
    required this.id,
    required this.name,
    required this.category,
    required this.status,
    required this.question,
    required this.requiredData,
    required this.conditions,
    required this.diagnostics,
    required this.output,
    required this.lessonId,
    required this.reference,
  });
}

const _v = MethodStatus.validated;
// Statut des méthodes à venir (aucune en développement en 1.36.0).
// ignore: unused_element
const _d = MethodStatus.inDevelopment;

/// Registre dans la langue courante.
List<MethodInfo> get methodRegistry =>
    currentLang == Lang.en ? [for (final m in _registryFr) _en[m.id]?.apply(m) ?? m] : _registryFr;

