MethodInfo? methodInfo(String id) {
  for (final m in methodRegistry) {
    if (m.id == id || id.startsWith(m.id)) return m;
  }
  // Variantes de calcul rattachées à une entrée du registre.
  const aliases = {
    't_test_student': 't_test_welch',
    'anova_welch': 'anova_oneway',
    'spearman': 'pearson',
    'sample_size_two_means': 'sample_size',
    'sample_size_two_proportions': 'sample_size',
    'sample_size_proportion': 'sample_size',
    'power_means': 'sample_size',
    'power_proportions': 'sample_size',
    'proportion_difference': 'proportion_ci',
    'describe_categorical': 'describe_numeric',
    'meta_or': 'meta_binary',
    'meta_rr': 'meta_binary',
    'meta_rd': 'meta_binary',
    'meta_md': 'meta_continuous',
    'meta_smd': 'meta_continuous',
    'meta_generic': 'meta_binary',
  };
  final a = aliases[id];
  return a == null ? null : methodInfo(a);
}

/// Matrice « question → données requises → méthode → conditions →
/// diagnostics → résultat » au format Markdown.
String methodMatrixMarkdown() {
  final b = StringBuffer()
    ..writeln(tr('| Question | Données requises | Méthode | Conditions | Diagnostics | Résultat | Statut | Référence de validation |',
        '| Question | Required data | Method | Conditions | Diagnostics | Output | Status | Validation reference |'))
    ..writeln('|---|---|---|---|---|---|---|---|');
  for (final m in methodRegistry) {
    final sep = tr(' ; ', '; ');
    b.writeln('| ${m.question} | ${m.requiredData} | ${m.name} | ${m.conditions.join(sep)} | ${m.diagnostics.join(sep)} | '
        '${m.output} | ${m.status == MethodStatus.validated ? tr("validée", "validated") : tr("**en développement**", "**in development**")} | ${m.reference} |');
  }
  return b.toString();
}

/// Textes anglais du registre (l'identifiant, le statut et la leçon restent ceux du registre français).
class _EnText {
  final String name, category, question, requiredData, output, reference;
  final List<String> conditions, diagnostics;
  const _EnText(this.name, this.category, this.question, this.requiredData, this.conditions, this.diagnostics, this.output, this.reference);
  MethodInfo apply(MethodInfo m) => MethodInfo(
      id: m.id,
      name: name,
      category: category,
      status: m.status,
      question: question,
      requiredData: requiredData,
      conditions: conditions,
      diagnostics: diagnostics,
      output: output,
      lessonId: m.lessonId,
      reference: reference);
}

